		classification = 7007011,
		id = 700701109,
		offset_y = 0,
		dec = "于是，二人就这么带着小狗，走在学院的草地上，懒洋洋地散着步。而，距校园十几公里开外的某处，正在执行任务的某学员，连着打了好几个喷嚏。"
