		classification = 7021011,
		id = 702101104,
		icon = "12340",
		offset_y = 0,
		dec = "<p>索菲亚外出执行任务了，我自己在对喵球做定期维护，但是途中出了点小问题，需要精密零件和<span style=color: rgb(0,216,255);>6个电子元件</span>，但我没有相关车间的认证权限，没法进行相关操作。</p>"
